import {ALL_DAYS,ALL_SESSIONS,formatDate} from './model.mjs';
const host=document.querySelector('#semester-canvas'),stage=document.querySelector('.semester-stage'),grid=document.querySelector('#date-grid');
const complete=date=>ALL_SESSIONS.filter(s=>s.date===date).every(s=>s.endAt<=new Date());
grid.innerHTML=ALL_DAYS.map(date=>`<time class="${complete(date)?'past':''}" datetime="${date}">${formatDate(date)}</time>`).join('');
let started=false;const lazy=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&!started){started=true;lazy.disconnect();start().catch(()=>{stage.classList.remove('has-webgl');stage.dataset.renderer='fallback';});}},{rootMargin:'900px'});lazy.observe(stage);
async function start(){
 const T=await import('./vendor/three.module.js');let renderer;try{renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});}catch{stage.dataset.renderer='fallback';return;}
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor(0x000000,0);renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;host.appendChild(renderer.domElement);
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(36,1,.1,60),group=new T.Group();scene.add(group);camera.position.set(0,0,12);
 const metal=new T.MeshStandardMaterial({color:0x718bad,metalness:.75,roughness:.26});const back=new T.MeshStandardMaterial({color:0x182b46,metalness:.65,roughness:.3});const geometry=new T.BoxGeometry(1.02,1.4,.055);const textures=[],materials=[],cards=[];
 const light=new T.DirectionalLight(0xe9f1ff,3);light.position.set(-3,5,7);scene.add(light);const rim=new T.DirectionalLight(0x77adff,4);rim.position.set(5,-2,-3);scene.add(rim);scene.add(new T.HemisphereLight(0xe5efff,0x21385b,2));
 ALL_DAYS.forEach((date,i)=>{const done=complete(date),surface=document.createElement('canvas');surface.width=256;surface.height=352;const c=surface.getContext('2d');c.fillStyle=done?'#182332':'#e8eef8';c.fillRect(0,0,256,352);c.strokeStyle=done?'#3b4d67':'#b4c2d8';c.lineWidth=2;c.strokeRect(12,12,232,328);c.fillStyle=done?'#9eb1cc':'#33445d';c.font='18px sans-serif';c.fillText(formatDate(date,{month:'short'}).toUpperCase(),30,51);c.font='bold 102px sans-serif';c.fillText(String(+date.slice(-2)).padStart(2,'0'),25,191);c.font='18px sans-serif';c.fillText(formatDate(date,{weekday:'long'}),30,240);c.font='14px sans-serif';c.fillText('FALL 2026',30,310);const texture=new T.CanvasTexture(surface);texture.colorSpace=T.SRGBColorSpace;textures.push(texture);const face=new T.MeshStandardMaterial({map:texture,metalness:.08,roughness:.48});materials.push(face);const mesh=new T.Mesh(geometry,[metal,metal,metal,metal,face,back]);group.add(mesh);cards.push(mesh);});
 let progress=0,trigger,raf=0,visible=true;const pointer={x:0,y:0};
 function render(){raf=0;const t=progress,spread=T.MathUtils.smoothstep(t,.08,.88),aspect=host.clientWidth/host.clientHeight;camera.position.z=aspect<.85?14.8:12.9;camera.lookAt(0,0,0);
  cards.forEach((card,i)=>{const a=i/ALL_DAYS.length*Math.PI*2;const x=Math.cos(a)*2.5,y=Math.sin(a)*2.5,z=Math.sin(a*2)*.4-i*.01;const gx=(i%7-3)*.94,gy=(2.5-Math.floor(i/7))*1.08;
   card.position.set(T.MathUtils.lerp(x,gx,spread),T.MathUtils.lerp(y,gy,spread),T.MathUtils.lerp(z,0,spread));card.rotation.set(T.MathUtils.lerp(.16,0,spread),T.MathUtils.lerp(.35,0,spread),T.MathUtils.lerp(a-Math.PI/2,0,spread));card.scale.setScalar(T.MathUtils.lerp(.84,.8,spread));
  });group.rotation.set((1-spread)*.2+pointer.y*.035,(1-spread)*-.35+pointer.x*.06,(1-spread)*(-.2+t*.4));renderer.render(scene,camera);host.dataset.progress=progress.toFixed(3);}
 function draw(){if(visible&&!raf)raf=requestAnimationFrame(render);}
 function resize(){const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();draw();}
 function configure(){trigger?.kill();if(window.siteMotionEnabled!==false&&window.ScrollTrigger){trigger=window.ScrollTrigger.create({id:'date-sculpture',trigger:'.semester-scroll',start:()=>innerWidth<768?'top top+=66':'top top+=80',end:'bottom bottom',onUpdate:self=>{progress=self.progress;draw();},onRefresh:self=>{progress=self.progress;draw();}});}else progress=1;draw();}
 const resizeObserver=new ResizeObserver(resize);resizeObserver.observe(host);const visibility=new IntersectionObserver(e=>{visible=e[0].isIntersecting;if(visible)draw();});visibility.observe(host);
 stage.classList.add('has-webgl');stage.dataset.renderer='webgl';resize();configure();window.addEventListener('site-motion-change',configure);host.addEventListener('pointermove',e=>{if(window.siteMotionEnabled===false)return;const r=host.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width-.5;pointer.y=(e.clientY-r.top)/r.height-.5;draw();});host.addEventListener('pointerleave',()=>{pointer.x=pointer.y=0;draw();});
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();trigger?.kill();stage.classList.remove('has-webgl');stage.dataset.renderer='fallback';});
 window.addEventListener('pagehide',e=>{if(e.persisted)return;trigger?.kill();resizeObserver.disconnect();visibility.disconnect();cancelAnimationFrame(raf);geometry.dispose();textures.forEach(t=>t.dispose());materials.forEach(m=>m.dispose());metal.dispose();back.dispose();renderer.dispose();},{once:true});
}
